-- Coffees: a link to each coffee on its roaster's website (its product page), to read about it and to
-- order it again; a button on its card on the Coffees page opens it. Kept trimmed; a link starts with
-- http:// or https://.
alter table public.coffees add column link text
  check (char_length(link) <= 500 and link ~* '^https?://[^\s/]+\S*$');

create or replace function public.coffee_link_rules() returns trigger
language plpgsql set search_path = ''
as $$
begin
  new.link := nullif(btrim(new.link), '');
  return new;
end $$;
create trigger coffees_link_rules before insert or update on public.coffees
  for each row execute function public.coffee_link_rules();

-- Easy Beans (business 1): Puchero's Brasil Fazenda Boa Vista (the `coffee_suppliers` migration) gets its
-- page on Puchero's shop and, as the owner asked, a photo of a Puchero bag (its label names another of
-- their coffees; a photo of this one can replace it on the Coffees page). Each only while still empty,
-- so neither a photo nor a link the café has put on it by then is changed. Easy Beans is business 1 when
-- it's named so or Aron is on its team; anywhere else nothing changes, and running it again changes nothing.
do $$
begin
  if not exists (select 1 from public.business b
                  where b.id = 1
                    and (b.name ~* 'easy\s*beans'
                         or exists (select 1 from public.profiles p where p.business_id = 1 and p.full_name ~* '^\s*aron\M'))) then
    return;
  end if;
  -- Named, so the rules see Easy Beans (a migration runs signed out).
  perform set_config('app.business_id', '1', true);
  update public.coffees
     set link = coalesce(link, 'https://somospuchero.com/producto/brasil-fazenda-boa-vista-natural-espresso/'),
         photo = coalesce(photo, 'data:image/jpeg;base64,')
   where business_id = 1 and name ~* 'boa\s*vista';
  perform set_config('app.business_id', '', true);
end $$;
